/*
 * Public Cloudinary URLs are accepted only for the configured cloud and for
 * immutable, project-scoped IDs generated by our signed upload endpoint.
 * A path remains in section JSON for backward-compatible ownership checks;
 * URL is the actual image delivery location.
 */
export const CLOUDINARY_PREFIX = "natsx/portfolio";

export function isTrustedCloudinaryUrl(
  input: string,
  logicalPath?: string,
): boolean {
  const cloudName =
    process.env.NEXT_PUBLIC_CLOUDINARY_CLOUD_NAME?.trim();

  if (!cloudName || !/^[a-zA-Z0-9_-]+$/.test(cloudName)) {
    return false;
  }

  try {
    const url = new URL(input);
    if (
      url.protocol !== "https:" ||
      url.hostname !== "res.cloudinary.com" ||
      url.port ||
      url.username ||
      url.password ||
      url.search ||
      url.hash
    ) {
      return false;
    }

    const prefix = `/${cloudName}/image/upload/`;
    if (!url.pathname.startsWith(prefix)) {
      return false;
    }

    const remainder = url.pathname.slice(prefix.length);
    // Require immutable version IDs, no transformations or external fetch URLs.
    const match = /^v\d+\/(natsx\/portfolio\/projects\/.+)$/.exec(remainder);
    if (!match || match[1].includes("..") || match[1].includes("%")) {
      return false;
    }

    if (logicalPath) {
      const expected = `${CLOUDINARY_PREFIX}/${logicalPath.replace(/\.[^.\/]+$/, "")}`;
      const extensionPattern = /\.(?:avif|gif|jpe?g|png|webp)$/i;
      return extensionPattern.test(match[1]) &&
        match[1].replace(extensionPattern, "") === expected;
    }

    return /^natsx\/portfolio\/projects\/[a-z0-9-]+\/(?:covers|sections)\//i.test(match[1]);
  } catch {
    return false;
  }
}
